		// For each fixed j (column), trav_j.for_each iterates over all i.
		traverser(A_trail, R_trail)
			.template for_dims<'j'>([&](auto trav_j) {
				// trav_j has 'j' fixed and iterates remaining dimension(s) (here 'i').

				// Accumulate R[k][j] = sum_i Q[i][k] * A[i][j]
