					// Q_col_k ignores 'j' and uses only 'i' (extra indices in state are fine).
					const num_t q_ik = Q_col_k[state];
					const num_t a_ij = A_trail[state];
					r_kj += q_ik * a_ij;
				});

				// Store R[k][j] for this column.
				// trav_j.state() carries the fixed 'j' index inside the shifted
				// trailing view, so R_trail[trav_j.state()] corresponds to
