	DEFINE_PROTO_STRUCT(r_layout, j_vec ^ k_vec);

	// Simple tuning knob that could be used for further blocking along 'i'
	// (currently not exploited for extra blocking, but kept here to make
	// the kernel easy to tune for specific hardware if extended).
	static constexpr std::size_t i_block = 128;
} tuning;


