// QR Decomposition with Modified Gram-Schmidt
//
// Original PolyBench pseudocode:
//
// for (k = 0; k < n; k++) {
//   nrm = 0;
//   for (i = 0; i < m; i++)
//     nrm += A[i][k] * A[i][k];
//   R[k][k] = sqrt(nrm);
