	// R has dimensions 'k' (rows) and 'j' (columns), both of length n.
	// The default traversal order is 'k' outer, 'j' inner, which matches
	// the original nested loops over k and then j.
	traverser(R).for_each([&](auto kj_state) {
		auto [k, j] = get_indices<'k', 'j'>(kj_state);

		// We only touch the upper-triangular part, leaving the lower
		// triangle as zero (already initialized in init_array).
		if (j < k)
			return;

		// --- Diagonal element: process column k (build Q[:,k] and R[k,k]) ---
		if (j == k) {
			// Views of k-th column of A and Q: A[:, k], Q[:, k]
			auto A_col_k = A ^ fix<'j'>(k);
			auto Q_col_k = Q ^ fix<'j'>(k);

